    .get_mode = regulator_fake_get_mode,
    .get_error_flags = regulator_fake_get_error_flags,
    .get_status = regulator_fake_get_status,
};

/* Device definition */
#define DT_DRV_COMPAT zephyr_regulator_fake

static int regulator_fake_init(const struct device *dev)
{
    ARG_UNUSED(dev);
    LOG_DBG("Fake regulator %s initialized", dev->name);
    return 0;
}

/* Define the fake device for each instance found in the device tree. */
#define REGULATOR_FAKE_INIT_DEVICE(inst) \
    DEVICE_DT_INST_DEFINE(inst, \
                          regulator_fake_init, \
                          NULL, \
                          NULL, \
                          NULL, \
                          POST_KERNEL, \
                          CONFIG_REGULATOR_INIT_PRIORITY, \
                          &regulator_fake_api);

DT_INST_FOREACH_STATUS_OKAY(REGULATOR_FAKE_INIT_DEVICE)
